  var sameDs = function (a, b) { return !!a && !!b && a.type === b.type && a.uid === b.uid && a.name === b.name; };
  var dsOf = function (d) { return { type: d.type, uid: d.uid, name: d.name }; };

  /* =========================== SESSION (logic, no DOM) =========================== */
  function createAppSession(deps) {
    deps = deps || {};
    var api = deps.api;
    var now = deps.now || Date.now;
    var G = deps.global || {};
    var listeners = [];
    var ctl = null, handle = null, searchHandle = null;
    var S = { appVersion: APP_VERSION, phase: 'INIT', checks: [], selfCheck: null, ready: false, query: '',
      search: null, candidates: [], selected: null, selection: null, target: null, plan: null, run: null, result: null, model: null, integrity: [],
      errors: [], notices: [], outputs: {}, reportShown: 0 };

    function emit() { listeners.forEach(function (f) { try { f(S); } catch (e) { /* a view error never breaks the session */ } }); }
    function fail(msg) { S.errors.push(msg); emit(); return false; }
    var busy = function () { return !!handle || !!searchHandle || S.phase === 'RUNNING' || S.phase === 'SEARCHING'; };

    function init() {
      S.checks = []; S.errors = [];
      var add = function (check, ok, detail) { S.checks.push({ check: check, ok: !!ok, detail: String(detail) }); };
      if (!api) { add('v7 bundle loaded', false, 'TAC_V7 not found on this page'); S.phase = 'BLOCKED'; emit(); return S; }
      add('v7 bundle loaded + version', api.version === EXPECT.version, api.version + (api.version === EXPECT.version ? '' : ' (expected ' + EXPECT.version + ')'));
      if (api.version !== EXPECT.version || !api.catalogue || !api.full || !api.controller || typeof api.controller.isRegionalDatasource !== 'function' || !api.dashboard || !api.ui || !api.text || !api.search || typeof api.selfCheck !== 'function') {
        add('v7 API complete', false, 'a different or incomplete TAC_V7 is loaded on this page - reload the tab and load the app again');
        S.ready = false; S.phase = 'BLOCKED'; emit(); return S;
      }
      var cat = api.catalogue, cerr = cat.validateAll();
      add('catalogue valid', cerr.length === 0 && cat.contracts.length === EXPECT.contracts, cat.contracts.length + ' diagnostic contracts' + (cerr.length ? '; ' + cerr[0] : ''));
      var origin = deps.getOrigin ? deps.getOrigin() : null;
      var allowO = api.controller.ALLOWED_ORIGINS;
      add('origin allowlist (pinned)', allowO.length === 1 && allowO[0] === EXPECT.origin, Array.prototype.join.call(allowO, ', '));
      add('current origin allowlisted', allowO.indexOf(origin) >= 0, String(origin));
      var dss = api.controller.ALLOWED_DATASOURCES;
      add('approved datasource name + UID', dss.length === 1 && sameDs(dss[0], EXPECT.datasource), Array.prototype.map.call(dss, function (d) { return d.name + ' / ' + d.uid; }).join(', '));
      add('full-investigation limits', api.full.DEFAULT_MAX_REQUESTS <= api.full.HARD_MAX_REQUESTS && api.full.HARD_MAX_REQUESTS <= 100,
        'default ' + api.full.DEFAULT_MAX_REQUESTS + ' / hard ceiling ' + api.full.HARD_MAX_REQUESTS + ' requests');
      var sc = api.selfCheck({ origin: origin, bootData: deps.getBootData ? deps.getBootData() : null });
      S.selfCheck = plain(sc);
      var bad = S.selfCheck.checks.filter(function (c) { return !c.ok; }).map(function (c) { return c.check + ': ' + c.detail; });
      add('zero-request self-check READY', sc.ready === true && sc.requestsMade === 0, 'requests made: ' + sc.requestsMade + (bad.length ? '; failing: ' + bad.join(' | ') : ''));
      add('live execution locked', sc.liveMode === 'LOCKED' && !G[ACTIVE_KEY], 'live mode ' + sc.liveMode + (G[ACTIVE_KEY] ? '; another live run is active in this tab' : ''));
      S.ready = S.checks.every(function (c) { return c.ok; });
      S.phase = S.ready ? 'READY' : 'BLOCKED';
      ctl = S.ready ? api.full.createFullController({ now: now }) : null;
      emit();
      return S;
    }

    function allContracts() { return api.catalogue.contracts.map(function (c) { return c.id; }); }
    /* rc.6: '' = this row may be investigated on its own datasource; otherwise the ACTUAL reason.
       The datasource must be a regional Prometheus datasource that THIS lookup's /api/datasources
       returned (exact uid + name) and that answered the tenant query (it produced this row). */
    function eligibility(c) {
      if (!c) return 'the row is no longer in the result list';
      if (!TENANT_RE.test(c.lcaasId || '')) return 'the tenant has no valid LCAAS ID';
      var d = c.datasource;
      if (!d || !api.controller.isRegionalDatasource(d)) return 'region ' + (c.region || '?') + ': the datasource is not a regional Prometheus datasource {type, uid, name}';
      if (!c.supported) return c.unsupportedReason || ('region ' + (c.region || '?') + ' is not available for investigation');
      var regs = (S.search && S.search.regions) || [];
      var listed = regs.some(function (r) { return r.datasource === d.name && r.uid === d.uid; });
      if (!listed) return 'datasource ' + d.name + ' (' + d.uid + ') was not returned by this session\'s Grafana datasource list';
      if (d.name.slice(0, 2) !== c.region) return 'region ' + c.region + ' does not match datasource ' + d.name;
      return '';
    }
    function checkPlan(pv, id, binding) {
      if (!pv || !pv.ok || pv.kind !== 'FULL') return 'preview not valid';
      if (pv.limits.retries !== 0) return 'retries are not 0';
      if (pv.limits.requests > pv.limits.maxRequests || pv.limits.maxRequests > api.full.HARD_MAX_REQUESTS) return 'request budget exceeded';
      if (!sameDs(pv.datasource, binding)) return 'datasource differs from the tenant\'s regional datasource';
      if (pv.lcaasId !== id) return 'tenant differs';
      var sel = 'lcaas_id="' + id + '"';
      for (var i = 0; i < pv.queries.length; i++) if (pv.queries[i].expr.indexOf(sel) < 0) return 'query ' + pv.queries[i].key + ' is not scoped to the tenant';
      return null;
    }

    function setQuery(v) {
      if (busy()) return;
      S.query = String(v == null ? '' : v).replace(/[\u0000-\u001f]/g, ' ').trim().slice(0, 128);
    }

    /* ---- discovery (search) ---- */
    function doSearch(realFetch) {
      var origin = deps.getOrigin();
      var ts;
      try { ts = api.search.createTenantSearch({ fetch: realFetch, now: now, licenceForAll: true }); } catch (e) { return fail('Search not available: ' + e.message); }
      S.search = { status: 'RUNNING', input: S.query, phase: 'datasources', sent: 0, startedAt: now() };
      S.candidates = []; S.selected = null; S.selection = null; S.target = null; S.plan = null; S.run = null; S.model = null; S.result = null; S.outputs = {}; S.integrity = [];
      try {
        searchHandle = ts.search(S.query, { origin: origin, onProgress: function (p) { if (S.search) { S.search.phase = p.phase; S.search.sent = p.sent; S.search.branch = p.branch || S.search.branch; } emit(); } });
      } catch (e) { searchHandle = null; S.search = null; return fail('Search refused: ' + e.message + '. Nothing was sent.'); }
      S.phase = 'SEARCHING';
      emit();
      searchHandle.done.then(function (res) {
        searchHandle = null;
        S.search = plain(res);
        S.candidates = S.search.candidates || [];
        S.phase = 'RESULTS';
        if (res.status === 'INVALID' || res.status === 'FAILED') S.errors.push(res.error);
        else if (res.status === 'NO_MATCH') S.notices.push('No tenant matched "' + res.input + '" on ' + (res.regions || []).length + ' regional datasource(s).');
        else if (res.status === 'MATCHES' && res.incomplete) S.errors.push(res.error || 'Some regional queries failed - the list may be incomplete.');
        else if (res.status === 'CANCELLED') S.notices.push('Search cancelled - no conclusion can be drawn about this tenant.');
        /* rc.4: automatic investigation ONLY for one verified match of THIS completed lookup */
        var why = autoRunBlocker(res);
        if (why === null) {
          S.notices.push('Exactly one authorized tenant matched - starting the read-only investigation.');
          if (!investigate(S.candidates[0], realFetch, 0)) emit();
          return;
        }
        if (res.status === 'MATCHES' && S.candidates.length === 1 && why) S.notices.push('Not started automatically: ' + why + '.');
        emit();
      }, function (e) { searchHandle = null; S.phase = 'RESULTS'; fail('Search error: ' + (e && e.message || e)); });
      return true;
    }
    /* rc.4: null = safe to auto-run; otherwise the reason (string). Every condition is re-checked here
       even though the search computes autoRun itself. */
    function autoRunBlocker(res) {
      if (!res || res.status !== 'MATCHES') return '';
      var cs = res.candidates || [];
      if (cs.length !== 1) return '';
      var c = cs[0];
      if (res.autoRun !== true) return res.incomplete ? 'some regional lookups failed, so another matching tenant cannot be excluded'
        : res.capped ? 'the result list was capped' : !c.supported ? (c.unsupportedReason || 'region ' + (c.region || '?') + ' is not available for investigation')
        : res.kind !== 'exact' ? 'the search was not an exact identifier' : 'the lookup did not verify a single tenant';
      if (res.incomplete || res.capped || (res.failures || []).length || (res.refused || []).length) return 'the lookup did not complete on every regional datasource';
      if (res.kind !== 'exact') return 'the search was not an exact identifier';
      var why = eligibility(c);
      return why ? why : null;
    }

    /* ---- diagnostics (full investigation) ---- */
    function investigate(c, realFetch, idx) {
      if (!c || !TENANT_RE.test(c.lcaasId || '')) return fail('Refused: the selected tenant has no valid lcaas_id. Nothing was sent.');
      var why = eligibility(c);
      if (why) return fail('Refused: ' + why + '. Nothing was sent.');
      var origin = deps.getOrigin();
      if (api.controller.ALLOWED_ORIGINS.indexOf(origin) < 0) return fail('Refused: page origin is not allowlisted. Nothing was sent.');
      if (G[ACTIVE_KEY] || handle) return fail('Refused: another live run is active in this tab.');
      /* rc.6: per-run binding = the exact datasource that returned THIS row; one controller per run */
      var binding = dsOf(c.datasource), runCtl;
      try { runCtl = api.full.createFullController({ now: now, allowedDatasources: [binding] }); } catch (e) { return fail('Refused: ' + e.message + '. Nothing was sent.'); }
      /* rc.4: the summary of the ONE tenant being investigated (bound from this row only) */
      if (typeof idx === 'number') { S.selected = idx; S.selection = selectionOf(c, idx); }
      /* fresh plan at the click: pure, no request */
      var pv = runCtl.preview({ origin: origin, lcaasId: c.lcaasId, datasource: dsOf(binding), contractIds: allContracts(), metadata: true, clcs: true });
      if (!pv.ok) return fail('Plan refused: ' + pv.errors.join('; ') + '. Nothing was sent.');
      var bad = checkPlan(pv, c.lcaasId, binding);
      if (bad) return fail('Plan rejected: ' + bad + '. Nothing was sent.');
      var phrase = pv.confirmationPhrase;
      if (phrase !== 'RUN FULL ' + c.lcaasId + ' ON ' + binding.name + ' PLAN ' + pv.planHash.slice(0, 12)) return fail('Internal plan binding mismatch. Nothing was sent.');
      S.target = plain(c);
      S.plan = { planHash: pv.planHash, queries: plain(pv.queries), limits: plain(pv.limits), contractIds: plain(pv.contractIds), createdAt: pv.createdAt, datasource: plain(binding) };
      var run = S.run = { startedAt: now(), finishedAt: null, planHash: pv.planHash, plannedRequests: pv.limits.requests, plannedItems: pv.limits.planItems,
        tenant: c.lcaasId, customer: c.customer || null, region: c.region, datasource: binding.name, datasourceUid: binding.uid,
        sent: 0, httpOk: 0, httpErrors: 0, aborted: 0, networkErrors: 0, completed: 0, finite: 0, noSeries: 0, nonFinite: 0, errors: 0, unusable: 0, metaSettled: 0, metaWithValue: 0,
        metaPlanned: pv.queries.filter(function (q) { return q.contractId === 'META'; }).length,
        progress: null, cancelRequested: false, status: 'RUNNING' };
      var observe = function (url, init) {                         // pass-through observer behind the controller gates
        run.sent++; emit();
        return Promise.resolve().then(function () { return realFetch(url, init); }).then(function (r) {
          if (r.ok) run.httpOk++; else run.httpErrors++;
          emit(); return r;
        }, function (e) {
          if (e && e.name === 'AbortError') run.aborted++; else run.networkErrors++;
          emit(); throw e;
        });
      };
      var onQueryResult = function (q) {
        run.completed++;
        if (q.contractId === 'META') {                              // tenant-details queries never count as diagnostic errors
          run.metaSettled++; if (FINITE[q.state]) run.metaWithValue++;
          emit(); return;
        }
        if (FINITE[q.state]) run.finite++;
        else if (q.state === 'NO_SERIES') run.noSeries++;
        else if (q.state === 'DATA_NON_FINITE') run.nonFinite++;
        if (!USABLE[q.state]) run.unusable++;
        if (!COMPLETED[q.state] && q.sent) run.errors++;           // sent but not completed (HTTP / query error, timeout, abort)
        emit();
      };
      G[ACTIVE_KEY] = true;
      try {
        handle = runCtl.start(pv, { confirmation: phrase, fetch: observe, origin: origin, onQueryResult: onQueryResult,
          onProgress: function (p) { run.progress = plain(p); emit(); } });
      } catch (e) {
        G[ACTIVE_KEY] = false; handle = null; S.run = null;
        return fail('Controller refused the run: ' + e.message + '. Nothing was sent.');
      }
      S.phase = 'RUNNING';
      emit();
      handle.done.then(function (out) { finish(out, null); }, function (e) { finish(null, e); });
      return true;
    }

    /* rc.2: ONE selected tenant per investigation. Selecting sends nothing and reads no fetch.
       rc.4: no Select step in the UI; selectionOf() records the row that Run Investigation bound. */
    function selectionOf(c, i) {
      var why = eligibility(c);
      var approved = !why;
      var lic = c.licence || null;
      return { index: i, customer: c.customer || null, lcaasId: c.lcaasId, tenantId: c.projectId || null,
        projectId: c.projectId || null, xdrId: c.xdrId || null, region: c.region || null, metroId: c.metroId || null,
        datasource: c.datasource ? c.datasource.name : null, datasourceUid: c.datasource ? c.datasource.uid : null, datasourceApproved: approved,
        licence: { text: lic ? lic.text : 'Not read', tone: lic ? lic.tone : 'na', badge: licenceBadge(lic) },
        blocked: approved ? '' : 'Investigation unavailable: ' + why + '. Nothing will be sent.' };
    }
    /* The only trigger. o.action: 'search' (default) or 'investigate' with o.index = the row whose
       Run Investigation button was clicked. The page fetch is read here, at the trusted click, never
       on load. (A single verified match is investigated from doSearch with the same fetch.) */
    function start(o) {
      o = o || {};
      S.errors = []; S.notices = [];
      if (!o.userGesture) return fail('Refused: search and investigation start only from a click (or Enter) by the operator.');
      if (!S.ready || !ctl) return fail('Environment checks have not passed - nothing can be sent.');
      if (busy()) return fail('Refused: a search or investigation is already running.');
      if (G[ACTIVE_KEY]) return fail('Refused: another live run is active in this tab.');
      var target = null;
      if (o.action === 'investigate') {
        if (S.phase !== 'RESULTS') return fail('Find a tenant first, then click Run Investigation on one row.');
        if (typeof o.index !== 'number' || o.index < 0 || o.index % 1 !== 0) return fail('Refused: click Run Investigation on one tenant row.');
        target = S.candidates[o.index];
        if (!target) return fail('Refused: that row is no longer in the result list.');
        if (typeof o.lcaasId === 'string' && o.lcaasId !== target.lcaasId) return fail('Refused: the row no longer matches the result list. Find the tenant again.');
        var X = selectionOf(target, o.index);
        if (!TENANT_RE.test(target.lcaasId || '')) return fail('Refused: this row has no valid LCAAS ID.');
        if (!X.datasourceApproved) return fail(X.blocked);
      } else {
        var cls = api.search.classify(S.query);
        if (!cls.ok) return fail(cls.error);
        if (cls.kind === 'name') return fail(NAME_SEARCH_BLOCKED);
      }
      var realFetch = deps.getFetch ? deps.getFetch() : null;       // read only now, never on load
      if (typeof realFetch !== 'function') return fail('Refused: browser fetch is not available.');
      return target ? investigate(target, realFetch, o.index) : doSearch(realFetch);
    }

    function cancel() {
      if (searchHandle && S.phase === 'SEARCHING') { searchHandle.cancel(); S.notices.push('Search cancel requested - nothing new is sent.'); emit(); return true; }
      if (!handle || S.phase !== 'RUNNING') return false;
      S.run.cancelRequested = true;
      handle.cancel();
      S.notices.push('Cancel requested - in-flight requests are aborted; nothing new is sent. Unanswered diagnostics stay UNKNOWN.');
      emit();
      return true;
    }

    function newInvestigation() {
      if (busy()) return false;
      S.phase = S.ready ? 'READY' : 'BLOCKED';
      S.query = ''; S.search = null; S.candidates = []; S.selected = null; S.selection = null; S.target = null; S.plan = null; S.run = null; S.result = null; S.model = null;
      S.integrity = []; S.outputs = {}; S.errors = []; S.notices = []; S.reportShown = 0;
      emit();
      return true;
    }

    /* post-run integrity: display-only facts, never upgrade a conclusion */
    function integrityOf(out, plan) {
      var p = [];
      if (out.sent > plan.limits.requests) p.push('sent ' + out.sent + ' > planned ' + plan.limits.requests);
      var planned = {};
      plan.queries.forEach(function (q) { planned[q.expr] = 1; });
      var seen = {};
      out.requestLog.forEach(function (l) {
        if (l.refused) p.push('second gate refused a request: ' + l.refused);
        if (!planned[l.expr]) p.push('request outside the plan');
        if (!l.refused) { if (seen[l.expr]) p.push('duplicate request'); seen[l.expr] = 1; }
      });
      (out.gateLog || []).forEach(function (g) { if (g && g.refused) p.push('live gate refused a request: ' + g.refused); });
      return p;
    }

    function finish(out, e) {
      G[ACTIVE_KEY] = false; handle = null;
      var run = S.run;
      if (run) run.finishedAt = now();
      if (e) {
        S.result = null; S.model = null;
        if (run) run.status = 'ERROR';
        S.errors.push('Run error: ' + (e && e.message || e) + '. No report was produced; nothing is reported as healthy.');
      } else {
        S.result = out;
        S.integrity = integrityOf(out, S.plan);
        try {
          /* complete captured response bodies go into the RESTRICTED model as raw evidence; SHAREABLE outputs drop them */
          S.model = plain(api.dashboard.buildDashboardModel(plain(out.report), { engineVersion: api.version, origin: out.origin,
            deploymentLabel: (run && run.region ? run.region + ' ' : '') + EXPECT.deployment + (run ? ' (' + run.datasource + ')' : ''), generatedAt: new Date(now()).toISOString(), tenantMeta: {},
            integrity: S.integrity, rawResponses: plain(out.responses || []) }));
          if (run) { run.status = S.model.execution.status; run.unknownDiagnostics = S.model.health.counts.UNKNOWN; }
        } catch (err) {
          S.model = null;
          S.errors.push('Report model could not be built: ' + (err && err.message || err));
        }
      }
      S.outputs = {};
      S.phase = 'DONE';
      emit();
      if (S.model) show('overlay');                                 // report opens automatically (Overview tab active)
    }

    /* ---- outputs (Phase 4F): ONE complete report per investigation, rendered once and cached.
       The live dashboard and the download are the same string. ---- */
    function output(kind) {
      if (!S.model) return { ok: false, error: 'No completed investigation yet.' };
      if (S.outputs[kind]) return S.outputs[kind];
      var m = S.model, r;
      if (kind === 'full') {
        var h = api.ui.renderFullReport(m, { appVersion: APP_VERSION });
        r = { ok: true, filename: h.filename, mime: 'text/html', text: h.html, data: plain(h.data) };
      } else if (kind === 'overview') {
        var o = api.text.renderOverviewText(m, { classification: 'RESTRICTED' });
        r = o.ok ? { ok: true, text: o.text } : { ok: false, error: 'overview not available' };
      } else return { ok: false, error: 'unknown output ' + kind };
      S.outputs[kind] = r;
      return r;
    }
    function save(kind) {
      if (kind !== 'full') return Promise.resolve(fail('Only the full report can be downloaded.'));
      var x = output('full');
      if (!x.ok) return Promise.resolve(fail(x.error));
      if (typeof deps.saveFile !== 'function') return Promise.resolve(fail('No save mechanism available.'));
      return Promise.resolve().then(function () { return deps.saveFile(x.filename, x.text, x.mime); }).then(function () {
        S.notices.push('Saved ' + x.filename + ' - ' + CONF_TITLE + ' ' + CONF_TEXT + ' Store it only in approved restricted storage.');
        emit(); return true;
      }, function (e) { return fail('Save cancelled or failed: ' + (e && e.message || e)); });
    }
    function copy(kind) {
      var x = output(kind);
      if (!x.ok) return Promise.resolve(fail(x.error));
      if (typeof deps.copyText !== 'function') return Promise.resolve(fail('Clipboard not available - use a download instead.'));
      return Promise.resolve().then(function () { return deps.copyText(x.text); }).then(function () {
        S.notices.push('Copied ' + kind + ' to the clipboard. Nothing was sent anywhere.'); emit(); return true;
      }, function (e) { return fail('Copy failed: ' + (e && e.message || e)); });
    }
    /* Unified dashboard toolbar actions handed to the report view (overlay bar). Copy Overview and
       Show / Hide Overview Text live inside the report document itself, so each control exists once. */
    var toolbar = Object.freeze({
      download: function () { return save('full'); },
      openTab: function () { return show('tab'); },
      newInvestigation: function () { var ok = newInvestigation(); if (ok && typeof deps.closeReport === 'function') { try { deps.closeReport(); } catch (e) { /* view only */ } } return ok; }
    });
    function show(mode) {
      var x = output('full');
      if (!x.ok) return fail(x.error);
      if (typeof deps.showReport !== 'function') return fail('No display mechanism available.');
      try { deps.showReport(x.text, mode === 'tab' ? 'tab' : 'overlay', x.filename, toolbar); } catch (e) { return fail('Could not display the report: ' + (e && e.message || e)); }
      S.reportShown++;
      emit();
      return true;
    }
    function copyPlan() {
      if (!S.plan) return Promise.resolve(fail('No plan yet.'));
      if (typeof deps.copyText !== 'function') return Promise.resolve(fail('Clipboard not available.'));
      var t = S.plan.queries.map(function (q, i) { return '#' + (i + 1) + ' ' + q.key + ' [' + (q.queryId || '-') + ']\n' + q.expr; }).join('\n\n');
      return Promise.resolve().then(function () { return deps.copyText(t); }).then(function () { S.notices.push('Copied the exact PromQL plan (' + S.plan.queries.length + ' queries).'); emit(); return true; });
    }

    return Object.freeze({
      init: init, setQuery: setQuery, start: start, cancel: cancel, newInvestigation: newInvestigation,
      output: output, save: save, copy: copy, show: show, copyPlan: copyPlan, toolbar: toolbar, rowStatus: selectionOf,
      executionSummary: function () { return S.model ? api.text.executionSummary(S.model) : null; },
      state: function () { return S; },
      subscribe: function (f) { listeners.push(f); },
      isActive: function () { return busy(); }
    });
  }

  /* ================================ VIEW (DOM) ================================ */
  /* rc.2: About Info - Explorer palette (green/teal gradient, slate text) */
  var C = { bg: '#ffffff', panel: '#f8fafc', line: '#e2e8f0', text: '#0f172a', dim: '#64748b', ok: '#16a34a', warn: '#d97706', bad: '#dc2626', info: '#0f766e', grey: '#94a3b8', brand: '#10b981' };
  var GRAD = 'linear-gradient(135deg,#0f766e 0%,#10b981 100%)';
  var RUNC = { COMPLETE: C.ok, PARTIAL: C.warn, CANCELLED: C.grey, DEADLINE: C.warn, CIRCUIT_OPEN: C.bad, REFUSED: C.bad, ERROR: C.bad, RUNNING: C.info };
  var TONE = { ok: C.ok, warn: C.warn, crit: C.bad, na: C.grey };
  /* CSS reused from About Info - Explorer ("tce-styles"), scoped to this panel. */
  var S_ = '#' + APP_ID + ' ';
